        ), renamed AS (
         SELECT 'AFR'::text AS ticker,
            (to_timestamp(((source."DateEpochMs" / 1000))::double precision) AT TIME ZONE 'UTC'::text) AS timezone,
            ((to_timestamp(((source."DateEpochMs" / 1000))::double precision) AT TIME ZONE 'UTC'::text))::date AS date_part,
            ((to_timestamp(((source."DateEpochMs" / 1000))::double precision) AT TIME ZONE 'UTC'::text))::time without time zone AS time_part,
            source."Interval",
            source."DateEpochMs",
            source."Open",
            source."Close",
            source."High",
            source."Low",
            source."Volume",
            source."Traded",
            source.file_date
           FROM source
        )
 SELECT ticker,
    timezone,
    date_part,
    time_part,
    "Interval",
    "DateEpochMs",
    "Open",
    "Close",
